//! C-alignment regression tests (step H6b: the page references of every statement kind follow C's cursors — the loops of
//! UPDATE / DELETE, uniqueness checks, triggers, UPSERT, index builds, VACUUM — and the engine's own reads no longer
//! touch the page cache). GENERATED by target/perf-work/h6b/gen_tests6b.py: every expected value is what C SQLite
//! 3.54.1 produces — size and FNV-1a hash of the database file C writes for the statements, and the rows C returns.
//! Cases marked "(The code before step H6b produced this ... too.)" guard code paths this step rewrote (they caught
//! its own mistakes while it was written); the others fail with the code before the step. Nothing here depends on files
//! outside the repository.
use crate::Connection;

fn fnv1a(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        h = (h ^ u64::from(b)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

struct TempDb(std::path::PathBuf);

impl TempDb {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("sqliters-h6b-{}-{name}.db", std::process::id()));
        let db = Self(path);
        db.remove_all();
        db
    }
    fn remove_all(&self) {
        for suffix in ["", "-journal", "-wal", "-shm"] {
            let mut s = self.0.clone().into_os_string();
            s.push(suffix);
            let _ = std::fs::remove_file(std::path::PathBuf::from(s));
        }
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        self.remove_all();
    }
}

fn assert_file_is_what_c_writes(name: &str, stmts: &[&str], c_size: usize, c_hash: u64) {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    for sql in stmts {
        // (a statement may fail, as it does in the C shell that produced the expected file:
        // the script goes on)
        let _ = conn.query(sql, &[]);
    }
    assert!(conn.try_close().is_ok());
    let bytes = std::fs::read(&db.0).unwrap();
    assert_eq!(bytes.len(), c_size, "{name}: file size");
    assert_eq!(fnv1a(&bytes), c_hash, "{name}: file content differs from C");
}

/// Runs the statements; `c_out` is what the C shell prints for them (rows as `a|b`, one per line; the lines of an
/// EXPLAIN QUERY PLAN are its `detail` column), `c_errors` the messages of the statements that fail, in order.
fn assert_rows_and_errors_are_what_c_returns(
    name: &str,
    stmts: &[&str],
    c_out: &str,
    c_errors: &[&str],
) {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    let mut out = String::new();
    let mut errors: Vec<String> = Vec::new();
    for sql in stmts {
        let eqp = sql.starts_with("EXPLAIN QUERY PLAN");
        match conn.query(sql, &[]) {
            Ok(res) => {
                for row in &res.rows {
                    let cells: Vec<String> = row
                        .values
                        .iter()
                        .map(|v| match v {
                            sqliters_types::Value::Null => String::new(),
                            sqliters_types::Value::Integer(i) => i.to_string(),
                            sqliters_types::Value::Real(r) => format!("{r:?}"),
                            sqliters_types::Value::Text(s) => s.to_string(),
                            sqliters_types::Value::Blob(b) => {
                                String::from_utf8_lossy(&b[..]).into_owned()
                            }
                        })
                        .collect();
                    if eqp {
                        out.push_str(cells.last().map_or("", String::as_str));
                    } else {
                        out.push_str(&cells.join("|"));
                    }
                    out.push('\n');
                }
            }
            Err(e) => errors.push(e.message.clone()),
        }
    }
    assert!(conn.try_close().is_ok());
    assert_eq!(out, c_out, "{name}: rows");
    assert_eq!(errors, c_errors, "{name}: error messages");
}

/// Runs the steps: a statement, or `@<suffix>` — the size of the file `<database><suffix>` at that point must be
/// what C has there (`u64::MAX`: no such file).
fn assert_file_sizes_are_what_c_has(name: &str, steps: &[&str], c_sizes: &[u64]) {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    let mut k = 0;
    for step in steps {
        if let Some(suffix) = step.strip_prefix('@') {
            let mut s = db.0.clone().into_os_string();
            s.push(suffix);
            let size = std::fs::metadata(std::path::PathBuf::from(s)).map_or(u64::MAX, |m| m.len());
            assert_eq!(size, c_sizes[k], "{name}: size of the file '{suffix}' at probe {k}");
            k += 1;
        } else {
            let _ = conn.query(step, &[]);
        }
    }
    assert_eq!(k, c_sizes.len());
    assert!(conn.try_close().is_ok());
}

