/// SELECTs through a secondary index (`c = ?`: index cursor, then the table row of each entry) and through a UNIQUE index (one row, no OP_Next) between the INSERTs of a transaction with cache_size=5: the pages their cursors fetch push dirty pages out of the cache; size of the journal and of the database file at four points.
#[test]
fn index_lookups_between_the_writes_of_a_transaction() {
    assert_file_sizes_are_what_c_has(
        "index_lookups_between_the_writes_of_a_transaction",
        &[
            "PRAGMA page_size=1024;",
            "PRAGMA cache_size=5;",
            "CREATE TABLE v(a INTEGER PRIMARY KEY, b TEXT UNIQUE, c INT, d INT);",
            "CREATE INDEX vc ON v(c);",
            "CREATE TABLE w(k INTEGER PRIMARY KEY, x TEXT);",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<1500) INSERT INTO v SELECT x, printf('%030d', x*7919%100003), x%97, x%11 FROM c;",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<40) INSERT INTO w SELECT x + 0, printf('%0200d', x) FROM c;",
            "SELECT a, b FROM v WHERE c = 1;",
            "SELECT a, b FROM v WHERE c = 2;",
            "SELECT a, b FROM v WHERE c = 3;",
            "SELECT a, b FROM v WHERE c = 4;",
            "SELECT a, b FROM v WHERE c = 5;",
            "SELECT a FROM v WHERE b = '000000000000000000000000046284';",
            "SELECT a FROM v WHERE b = '000000000000000000000000084649';",
            "SELECT a FROM v WHERE b = '000000000000000000000000044868';",
            "SELECT a FROM v WHERE b = '000000000000000000000000083233';",
            "SELECT a FROM v WHERE b = '000000000000000000000000043452';",
            "@-journal",
            "@",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<40) INSERT INTO w SELECT x + 100, printf('%0200d', x) FROM c;",
            "SELECT a, b FROM v WHERE c = 8;",
            "SELECT a, b FROM v WHERE c = 9;",
            "SELECT a, b FROM v WHERE c = 10;",
            "SELECT a, b FROM v WHERE c = 11;",
            "SELECT a, b FROM v WHERE c = 12;",
            "SELECT a FROM v WHERE b = '000000000000000000000000081817';",
            "SELECT a FROM v WHERE b = '000000000000000000000000020179';",
            "SELECT a FROM v WHERE b = '000000000000000000000000080401';",
            "SELECT a FROM v WHERE b = '000000000000000000000000018763';",
            "SELECT a FROM v WHERE b = '000000000000000000000000078985';",
            "@-journal",
            "@",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<40) INSERT INTO w SELECT x + 200, printf('%0200d', x) FROM c;",
            "SELECT a, b FROM v WHERE c = 15;",
            "SELECT a, b FROM v WHERE c = 16;",
            "SELECT a, b FROM v WHERE c = 17;",
            "SELECT a, b FROM v WHERE c = 18;",
            "SELECT a, b FROM v WHERE c = 19;",
            "SELECT a FROM v WHERE b = '000000000000000000000000017347';",
            "SELECT a FROM v WHERE b = '000000000000000000000000055712';",
            "SELECT a FROM v WHERE b = '000000000000000000000000015931';",
            "SELECT a FROM v WHERE b = '000000000000000000000000054296';",
            "SELECT a FROM v WHERE b = '000000000000000000000000014515';",
            "@-journal",
            "@",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<40) INSERT INTO w SELECT x + 300, printf('%0200d', x) FROM c;",
            "SELECT a, b FROM v WHERE c = 22;",
            "SELECT a, b FROM v WHERE c = 23;",
            "SELECT a, b FROM v WHERE c = 24;",
            "SELECT a, b FROM v WHERE c = 25;",
            "SELECT a, b FROM v WHERE c = 26;",
            "SELECT a FROM v WHERE b = '000000000000000000000000052880';",
            "SELECT a FROM v WHERE b = '000000000000000000000000091245';",
            "SELECT a FROM v WHERE b = '000000000000000000000000051464';",
            "SELECT a FROM v WHERE b = '000000000000000000000000089829';",
            "SELECT a FROM v WHERE b = '000000000000000000000000050048';",
            "@-journal",
            "@",
            "COMMIT;",
        ],
        &[3584, 163840, 3584, 174080, 3584, 184320, 3584, 194560],
    );
}

