/// DELETE / UPDATE whose loop finds no row (an empty table: `OP_Rewind` fetches the root page; an equality on an index without a match: `OP_SeekGE` with `BTREE_SEEK_EQ` leaves without a step; an empty rowid range: the seek itself) between INSERTs that fill the cache (cache_size=-40): each fetch can push a dirty page into the WAL. (The code before step H6b had these sizes too.)
#[test]
fn loops_over_empty_tables_fetch_the_root_page() {
    assert_file_sizes_are_what_c_has(
        "loops_over_empty_tables_fetch_the_root_page",
        &[
            "PRAGMA journal_mode=wal;",
            "PRAGMA cache_size=-40;",
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b TEXT, c INT);",
            "CREATE INDEX tc ON t(c);",
            "CREATE TABLE u(a INTEGER PRIMARY KEY, b TEXT);",
            "CREATE TABLE w(k TEXT PRIMARY KEY, v INT) WITHOUT ROWID;",
            "CREATE TABLE o(a INTEGER PRIMARY KEY, x BLOB);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<32) INSERT INTO o SELECT x + 0, zeroblob(4096 * 2 + x) FROM c;",
            "DELETE FROM t WHERE a % 5 = 0;",
            "@-wal",
            "UPDATE u SET b = b || 'yy';",
            "@-wal",
            "DELETE FROM t WHERE a BETWEEN 3 AND 9;",
            "@-wal",
            "DELETE FROM t WHERE c = 46;",
            "@-wal",
            "COMMIT;",
        ],
        &[300792, 300792, 300792, 300792],
    );
}

