/// Row triggers that write a second table (each trigger program has its own cursors) and an UPSERT, with a 10-page cache; then the tables are emptied. (The code before step H6b produced this file too.)
#[test]
fn row_triggers_and_upsert_under_a_small_cache() {
    assert_file_is_what_c_writes(
        "row_triggers_and_upsert_under_a_small_cache",
        &[
            "PRAGMA cache_size=10;",
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b TEXT, c INT UNIQUE, n INT DEFAULT 0);",
            "CREATE TABLE log(id INTEGER PRIMARY KEY, what TEXT, k INT);",
            "CREATE TRIGGER tu AFTER UPDATE ON t BEGIN INSERT INTO log(what, k) VALUES('u', old.a); END;",
            "CREATE TRIGGER td BEFORE DELETE ON t BEGIN INSERT INTO log(what, k) VALUES('d', old.a); END;",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<2500) INSERT INTO t(a,b,c) SELECT x, printf('%080d', x), x FROM c;",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<700) INSERT INTO t(a,b,c) SELECT x * 2, 'again', x * 2 + 5000000 FROM c WHERE true ON CONFLICT(a) DO UPDATE SET n = n + 1, b = excluded.b;",
            "UPDATE t SET n = n + 10 WHERE a % 4 = 0;",
            "DELETE FROM t WHERE a % 7 = 0;",
            "DELETE FROM log;",
            "DELETE FROM t;",
            "COMMIT;",
        ],
        307200,
        0x97c2ec23bf5646f2,
    );
}

