/// WAL mode, `SAVEPOINT s` as the transaction, an INSERT that changes page 1, `ROLLBACK TO s`, `RELEASE s`: the rollback reads page 1 back (`pagerUndoCallback` -> `readDbPage`), which sets `Pager.dbFileVers` to the counter of the last commit, so the commit that follows stamps that counter plus one.
#[test]
fn wal_commit_after_rollback_to_the_transaction_savepoint() {
    assert_file_is_what_c_writes(
        "wal_commit_after_rollback_to_the_transaction_savepoint",
        &[
            "PRAGMA page_size=512;",
            "PRAGMA journal_mode=wal;",
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b TEXT, c INT, d INT, e TEXT);",
            "INSERT INTO t VALUES(55,'w16',12,14,'w22');",
            "INSERT OR IGNORE INTO t(b,c,d,e) VALUES('w3',8,7,'w24');",
            "INSERT INTO t VALUES(39,'w0',11,NULL,NULL);",
            "INSERT INTO t VALUES(45,NULL,22,22,NULL);",
            "INSERT INTO t SELECT a + 71, b || 'x', c + 9, d, e FROM t WHERE a % 3 = 0;",
            "INSERT INTO t VALUES(1,'w3',3,NULL,'w14');",
            "DELETE FROM t WHERE d = 14;",
            "INSERT INTO t(b,c,d,e) VALUES('w25',2,NULL,'w7');",
            "INSERT INTO t VALUES(5,NULL,24,25,'w13');",
            "INSERT OR REPLACE INTO t VALUES(30,'w18',9,13,'w10');",
            "INSERT OR IGNORE INTO t VALUES(27,'w6',22,0,'w4');",
            "INSERT OR REPLACE INTO t VALUES(47,'w12',24,4,NULL);",
            "INSERT INTO t(b,c,d,e) VALUES('w16',21,4,NULL);",
            "INSERT INTO t VALUES(19,NULL,NULL,11,'w3');",
            "INSERT OR REPLACE INTO t SELECT a + 57, b || 'x', c + 2, d, e FROM t WHERE a % 2 = 0;",
            "INSERT INTO t VALUES(40,NULL,18,NULL,'w19');",
            "INSERT OR ABORT INTO t(b,c,d,e) VALUES('w24',7,NULL,'w7');",
            "INSERT OR FAIL INTO t(b,c,d,e) VALUES('w24',0,0,'w14');",
            "INSERT OR FAIL INTO t SELECT a + 58, b || 'x', c + 22, d, e FROM t WHERE a % 3 = 0;",
            "INSERT OR FAIL INTO t VALUES(22,'w1',1,0,'w15');",
            "INSERT OR IGNORE INTO t(b,c,d,e) VALUES('w9',10,13,'w4');",
            "INSERT INTO t(b,c,d,e) VALUES('w1',7,12,'w8');",
            "INSERT OR ROLLBACK INTO t(b,c,d,e) VALUES('w23',11,3,'w7');",
            "INSERT OR ABORT INTO t(b,c,d,e) VALUES('w10',10,11,'w4');",
            "SAVEPOINT s;",
            "INSERT INTO t VALUES(31,'w12',25,9,'w17');",
            "ROLLBACK TO s;",
            "RELEASE s;",
        ],
        1024,
        0xaffa933ac04e7f92,
    );
}

