/// A one-row INSERT that violates a UNIQUE constraint inside BEGIN .. COMMIT, on a table whose UNIQUE index is older than a plain index: C checks every constraint before its first write, so nothing of the row exists afterwards. The compiled insert program wrote the entry of the newer index before it checked the UNIQUE one and ran without a statement journal (as C does): the entry stayed (count(*) through that index 3, "wrong # of entries in index vc").
#[test]
fn failed_unique_insert_inside_a_transaction_leaves_nothing_behind() {
    assert_rows_and_errors_are_what_c_returns(
        "failed_unique_insert_inside_a_transaction_leaves_nothing_behind",
        &[
            "CREATE TABLE v(a INTEGER PRIMARY KEY, b TEXT UNIQUE, c INT);",
            "CREATE INDEX vc ON v(c);",
            "INSERT INTO v VALUES(1,'x',1),(2,'y',2);",
            "BEGIN;",
            "INSERT INTO v VALUES(1000, 'x', 1);",
            "INSERT INTO v(b, c) VALUES('y', 7);",
            "INSERT INTO v VALUES(1001, 'k', 1);",
            "COMMIT;",
            "SELECT count(*) FROM v;",
            "SELECT a, b, c FROM v NOT INDEXED ORDER BY a;",
            "SELECT count(*) FROM v INDEXED BY vc;",
            "PRAGMA integrity_check;",
        ],
        "3\n1|x|1\n2|y|2\n1001|k|1\n3\nok\n",
        &[
            "UNIQUE constraint failed: v.b",
            "UNIQUE constraint failed: v.b",
        ],
    );
}
